const toolCall = body?.message?.toolCalls?.[0] || body?.message?.toolCallList?.[0];

if (!toolCall) return [{ json: { status: 'failed', message: 'No tool call found', toolCallId: null } }];

const args = toolCall.function.arguments;
const toolCallId = toolCall.id;

const patientName = args.patientName || null;
const oldDate = args.oldDate || null;
const oldTime = args.oldTime || null;   // ← ADD THIS
const newDate = args.newDate || null;
const newTime = args.newTime || null;
const doctorId = args.doctorId || null;
const reason = args.reason || 'General Consultation';

if (!patientName || !oldDate || !oldTime || !newDate || !newTime || !doctorId) {
  return [{ json: { status: 'failed', message: 'Missing required fields', toolCallId } }];
}

const oldStart = new Date(`${oldDate}T${oldTime}:00+05:30`).toISOString();  // ← exact time now
const oldEnd = new Date(`${oldDate}T${oldTime}:00+05:30`);
oldEnd.setMinutes(oldEnd.getMinutes() + 30);

const newStartDt = new Date(`${newDate}T${newTime}:00+05:30`);
if (isNaN(newStartDt.getTime())) return [{ json: { status: 'failed', message: 'Invalid new date/time', toolCallId } }];

const newEndDt = new Date(newStartDt);
newEndDt.setMinutes(newEndDt.getMinutes() + 30);

return [{ json: {
  patientName, oldDate, oldTime, newDate, newTime, reason, doctorId,
  oldStart,
  oldEnd: oldEnd.toISOString(),
  newStart: newStartDt.toISOString(),
  newEnd: newEndDt.toISOString(),
  toolCallId
}}];

