const body = $json.body;
const toolCall = body?.message?.toolCalls?.[0] || body?.message?.toolCallList?.[0];
const toolCallId = toolCall?.id || null;
const args = toolCall?.function?.arguments || {};
const specialty = (args.specialty || '').toLowerCase().trim();

return [{ json: { specialty, toolCallId } }];

const items = $input.all();
const toolCallId = $('Extract Data7').item.json.toolCallId;
const specialty = $('Extract Data7').item.json.specialty;

let doctors = items
  .map(i => i.json)
  .filter(row => row.Active === 'TRUE' || row.Active === true);

if (specialty) {
  doctors = doctors.filter(d =>
    (d.Specialty || '').toLowerCase().includes(specialty)
  );
}

if (doctors.length === 0) {
  return [{ json: {
    results: [{
      toolCallId,
      result: specialty
        ? `No doctors found for ${specialty}. Available specialties are: ${[...new Set(items.map(i => i.json.Specialty).filter(Boolean))].join(', ')}.`
        : `No doctors are currently available.`
    }]
  }}];
}

const list = doctors.map(d => `${d.DoctorName} (${d.Specialty}), ID: ${d.DoctorID}`).join(' | ');

return [{ json: {
  results: [{
    toolCallId,
    result: `Available doctors: ${list}. Which doctor would you like to see?`
  }]
}}];

