const rows = $input.all().map(i => i.json);
const data = $('Get Calendar ID for Reschedule1').item.json;

const patientNameLower = data.patientName.toLowerCase();
const oldDate = data.oldDate;
const oldTime = data.oldTime;

const match = rows.find(row => {
  const nameMatch = (row.PatientName || '').toLowerCase().includes(patientNameLower);
  const dateMatch = (row.Date || '').includes(oldDate);
  const timeMatch = (row.Time || '').includes(oldTime);   // ← ADD TIME MATCH
  const doctorMatch = (row.DoctorName || '').toLowerCase().includes((data.doctorName || '').toLowerCase());
  return nameMatch && dateMatch && timeMatch && doctorMatch;
});

return [{ json: {
  ...data,
  appointmentId: match ? match.AppointmentID : null,
  sheetRowFound: !!match
}}];
